const fs = await import('node:fs');
const inputPath = process.env.INPUT_PATH;
const outputPath = process.env.OUTPUT_PATH;
if (!inputPath) throw new Error('INPUT_PATH env var required');
if (!outputPath) throw new Error('OUTPUT_PATH env var required');
if (!fs.existsSync(inputPath)) throw new Error('Input file does not exist: ' + inputPath);
globalThis.inputPath = inputPath;
globalThis.outputPath = outputPath;

const fs = await import('node:fs');
const { parse } = await import('csv-parse/sync');
const parquet = (await import('parquetjs')).default;
const inputPath = globalThis.inputPath;
const outputPath = globalThis.outputPath;
const csvContent = fs.readFileSync(inputPath, 'utf8');
const records = parse(csvContent, { columns: true, skip_empty_lines: true });
if (!records.length) throw new Error('No records found in CSV');
const firstRecord = records[0];
const schemaFields = {};
for (const [key, value] of Object.entries(firstRecord)) {
  const numVal = Number(value);
  if (!isNaN(numVal) && Number.isInteger(numVal)) {
    schemaFields[key] = { type: 'INT64' };
  } else {
    schemaFields[key] = { type: 'UTF8' };
  }
}
const schema = new parquet.ParquetSchema(schemaFields);
const writer = await parquet.ParquetWriter.openFile(schema, outputPath);
for (const record of records) {
  const row = {};
  for (const [key, value] of Object.entries(record)) {
    const numVal = Number(value);
    row[key] = (!isNaN(numVal) && Number.isInteger(numVal)) ? parseInt(value) : value;
  }
  await writer.appendRow(row);
}
await writer.close();
globalThis.parquetPath = outputPath;

